package local.skyfamily;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.graphics.*;import android.net.Uri;import android.view.*;import android.webkit.*;import android.widget.*;import java.util.*;import java.text.*;
public class MainActivity extends Activity {
 android.content.SharedPreferences prefs;LinearLayout body;WebView web;
 public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("sky",0);home();}
 void page(String title){if(web!=null){web.destroy();web=null;}LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(12,12,12,12);setContentView(root);Button back=new Button(this);back.setText("Home - "+title);back.setOnClickListener(v->home());root.addView(back);ScrollView sc=new ScrollView(this);root.addView(sc);body=new LinearLayout(this);body.setOrientation(1);sc.addView(body);}
 void text(String s){TextView t=new TextView(this);t.setText(s);t.setTextSize(21);body.addView(t);}
 void button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setTextSize(20);body.addView(b,new LinearLayout.LayoutParams(-1,70));b.setOnClickListener(v->r.run());}
 EditText input(String hint,String value){EditText e=new EditText(this);e.setHint(hint);e.setText(value);body.addView(e);return e;}
 String get(String k){return prefs.getString(k,"");}void save(String k,String v){prefs.edit().putString(k,v).apply();}void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 void home(){page("Sky Family");text(new SimpleDateFormat("EEEE, d MMMM yyyy",Locale.getDefault()).format(new Date()));button("Apps",()->apps());button("Calendar",()->calendar());button("Drawing",()->drawing(false));button("Colouring book",()->drawing(true));button("Daily word puzzle",()->puzzle());button("Daily notes",()->notes());button("Virtual pet",()->pet());button("Books and schoolwork",()->pick(false));button("Local photo or video",()->pick(true));button("Immich web panel",()->panel("immich"));button("ISS web panel",()->panel("iss"));button("News web panel",()->panel("news"));button("Live cameras",()->cameras());button("Settings",()->settings());}
 void apps(){page("Apps");Intent q=new Intent(Intent.ACTION_MAIN);q.addCategory(Intent.CATEGORY_LAUNCHER);List<ResolveInfo> list=getPackageManager().queryIntentActivities(q,0);Collections.sort(list,new ResolveInfo.DisplayNameComparator(getPackageManager()));for(ResolveInfo r:list){if(r.activityInfo.packageName.equals(getPackageName()))continue;button(r.loadLabel(getPackageManager()).toString(),()->{try{Intent i=new Intent();i.setComponent(new ComponentName(r.activityInfo.packageName,r.activityInfo.name));startActivity(i);}catch(Exception e){toast("Cannot launch app");}});}}
 void notes(){page("Notes");EditText date=input("yyyy-MM-dd",new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date()));EditText note=input("Note",get("note."+date.getText()));note.setMinLines(8);button("Load date",()->note.setText(get("note."+date.getText())));button("Save",()->{save("note."+date.getText(),note.getText().toString());toast("Saved");});}
 void calendar(){page("Calendar");CalendarView cal=new CalendarView(this);body.addView(cal,new LinearLayout.LayoutParams(-1,360));String[] day={new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date())};EditText event=input("Day entries",get("event."+day[0]));cal.setOnDateChangeListener((c,y,m,d)->{day[0]=String.format(Locale.US,"%04d-%02d-%02d",y,m+1,d);event.setText(get("event."+day[0]));});button("Save selected day",()->{save("event."+day[0],event.getText().toString());toast("Saved");});text("Local entries only; no calendar sync or alarms.");}
 void drawing(boolean outline){page(outline?"Colouring":"Drawing");Art art=new Art(this,outline);LinearLayout row=new LinearLayout(this);body.addView(row);for(int color:new int[]{Color.BLACK,Color.RED,Color.BLUE,Color.GREEN,Color.YELLOW,Color.WHITE}){Button b=new Button(this);b.setBackgroundColor(color);row.addView(b,new LinearLayout.LayoutParams(0,60,1));b.setOnClickListener(v->art.ink=color);}body.addView(art,new LinearLayout.LayoutParams(-1,600));button("Clear",()->art.clear());button("Save PNG",()->{try{java.io.File dir=new java.io.File(getExternalFilesDir(null),"drawings");dir.mkdirs();java.io.File f=new java.io.File(dir,"drawing-"+System.currentTimeMillis()+".png");java.io.FileOutputStream out=new java.io.FileOutputStream(f);art.bitmap.compress(Bitmap.CompressFormat.PNG,100,out);out.close();toast("Saved to app drawings folder");}catch(Exception e){toast(e.toString());}});}
 class Art extends View {Bitmap bitmap=Bitmap.createBitmap(1000,650,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);Paint p=new Paint(3);boolean outline;int ink=Color.BLACK;float px,py;Art(Context c,boolean o){super(c);outline=o;clear();}void clear(){canvas.drawColor(Color.WHITE);if(outline){p.setColor(Color.BLACK);p.setStrokeWidth(5);p.setStyle(Paint.Style.STROKE);canvas.drawRect(250,260,730,600,p);Path roof=new Path();roof.moveTo(180,260);roof.lineTo(490,40);roof.lineTo(800,260);roof.close();canvas.drawPath(roof,p);canvas.drawRect(440,420,540,600,p);canvas.drawCircle(860,90,55,p);}invalidate();}protected void onDraw(Canvas c){c.drawBitmap(bitmap,null,new Rect(0,0,getWidth(),getHeight()),null);}public boolean onTouchEvent(android.view.MotionEvent e){float x=e.getX()*1000/getWidth(),y=e.getY()*650/getHeight();if(e.getAction()==0){px=x;py=y;getParent().requestDisallowInterceptTouchEvent(true);}p.setColor(ink);p.setStrokeWidth(10);p.setStyle(Paint.Style.STROKE);p.setStrokeCap(Paint.Cap.ROUND);canvas.drawLine(px,py,x,y,p);px=x;py=y;invalidate();if(e.getAction()==1||e.getAction()==3)getParent().requestDisallowInterceptTouchEvent(false);return true;}}
 void puzzle(){page("Daily word");String[] words={"APPLE","BEACH","SPACE","FRAME","TRAIN","CLOUD","PLANT","BRUSH","LIGHT","OCEAN","HOUSE","RIVER","GREEN","STONE"};long day=System.currentTimeMillis()/86400000L;String answer=words[(int)(day%words.length)],key="puzzle."+day;text("Six guesses. + correct position; ? elsewhere; - absent. UTC daily reset. Small repeating word list.");TextView history=new TextView(this);history.setText(get(key));history.setTextSize(22);body.addView(history);EditText guess=input("Five letters","");button("Guess",()->{String old=get(key);if(old.contains("+++++")||old.split("\n").length>=6&&!old.isEmpty()){toast("Game finished");return;}String g=guess.getText().toString().trim().toUpperCase(Locale.US);if(!g.matches("[A-Z]{5}")){toast("Enter five letters");return;}char[] marks={'-','-','-','-','-'},remaining=answer.toCharArray();for(int i=0;i<5;i++)if(g.charAt(i)==remaining[i]){marks[i]='+';remaining[i]=' ';}for(int i=0;i<5;i++)if(marks[i]!='+')for(int j=0;j<5;j++)if(g.charAt(i)==remaining[j]){marks[i]='?';remaining[j]=' ';break;}String next=old+g+"  "+new String(marks)+"\n";save(key,next);history.setText(next);guess.setText("");});}
 void pet(){page("Pocket creature");int food=prefs.getInt("food",50),xp=prefs.getInt("xp",0);text((xp>=100?"Winged creature":xp>=30?"Young creature":"Egg creature")+"\nFood: "+food+" / 100\nTraining: "+xp);button("Feed",()->{prefs.edit().putInt("food",Math.min(100,food+10)).apply();pet();});button("Train",()->{if(food<5){toast("Feed first");return;}prefs.edit().putInt("food",food-5).putInt("xp",xp+5).apply();pet();});text("Original text-only prototype, not a Digimon game. No background ageing.");}
 void pick(boolean media){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");if(media)i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"image/*","video/*"});try{startActivityForResult(i,20);}catch(Exception e){toast("No document picker installed");}}
 protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(req==20&&res==RESULT_OK&&data!=null){Intent i=new Intent(Intent.ACTION_VIEW);Uri u=data.getData();i.setDataAndType(u,getContentResolver().getType(u));i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivity(i);}catch(Exception e){toast("Install a compatible reader/player first");}}}
 void panel(String key){String url=get(key);if(!url.startsWith("https://")&&!url.startsWith("http://")){toast("Set a trusted HTTP(S) URL in Settings");settings();return;}page(key);text("Web panel only. Android 4.4 may not support this site.");web=new WebView(this);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.setWebViewClient(new WebViewClient());body.addView(web,new LinearLayout.LayoutParams(-1,650));web.loadUrl(url);}
 void cameras(){page("Explore");text("Configure trusted camera page URLs in Settings. No streams bundled or live status verification.");for(String name:new String[]{"castles","beaches","nature","space"})button(name,()->panel("cam."+name));}
 void settings(){page("Settings");text("Trusted HTTP(S) URLs only. No API keys in URLs. HTTP is unencrypted. No native Immich or ISS integration yet.");for(String k:new String[]{"immich","iss","news","cam.castles","cam.beaches","cam.nature","cam.space"}){text(k);EditText e=input("https://...",get(k));button("Save "+k,()->{String s=e.getText().toString().trim();if(!s.isEmpty()&&!s.startsWith("https://")&&!s.startsWith("http://")){toast("Use HTTP(S)");return;}save(k,s);toast("Saved");});}}
 public void onBackPressed(){home();}
}
